/** "Tuesday, 20 October 2026" — empty for TBC dates. Parsed as UTC so the weekday never drifts. */
export const formatEventDate = (iso: string): string => {
  if (!iso) return "";
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return new Intl.DateTimeFormat("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  })
    .format(dt)
    .replace(/^(\w+) /, "$1, ");
};
